  FT["PH-H9001"] = {"id":"PH-H9001","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2013/ra_10549_2013.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Bacoor市","en":"An Act Converting the General Evangelista Provincial Road in the City of Bacoor, Province of Cavite into a National Road and Proving Funds Therefor","orig":"An Act Converting the General Evangelista Provincial Road in the City of Bacoor, Province of Cavite into a National Road and Proving Funds Therefor"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 10549","issuingBody":"Congress of the Philippines","promulgatedDate":"2013-05-15","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2013/ra_10549_2013.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H9001-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The 4.43-kilometer General Evangelista Provincial Road in the City of Bacoor, Province of Cavite is hereby converted into a national road under the jurisdiction of the Department of Public Works and Highways."}},{"id":"PH-H9001-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Public Works and Highways shall include in the Department’s program the improvement, maintenance and repair of the said road, the funding of which shall be included in the annual General Appropriations Act."}},{"id":"PH-H9001-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p128"};
